import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import {LicnaKarta} from "../models/LicnaKarta";

@Injectable({
  providedIn: 'root'
})
export class ZahteviService {

  private baseUrl = 'http://localhost:8080/licna-karta';

  constructor(private http: HttpClient) { }

  // Dohvati sve zahteve za prijavljenog korisnika
  getSviZahtevi(token: string): Observable<LicnaKarta[]> {
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.get<LicnaKarta[]>(`${this.baseUrl}/svi-zahtevi`, { headers });
  }

  // Opcionalno: metoda za podnošenje zahteva
  podnesiZahtev(token: string, zahtev: any): Observable<any> {
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.post(`${this.baseUrl}/zahtev`, zahtev, { headers, responseType: 'text' });
  }

  // Opcionalno: metoda za produženje lične
  produziLicnu(token: string): Observable<any> {
    const headers = new HttpHeaders().set('Authorization', `Bearer ${token}`);
    return this.http.post(`${this.baseUrl}/produzi`, null, { headers, responseType: 'text' });
  }
}
